// Validate incoming email response data
const input = $json || {};

const prospect_email = input.from || input.prospect_email || input.email || '';
const subject = input.subject || '';
const body = input.body || input.text || input.snippet || '';
const prospect_name = input.prospect_name || input.name || '';
const received_at = input.received_at || input.date || new Date().toISOString();

if (!prospect_email && !body) {
  return [{ json: {
    error: true,
    message: 'Missing required fields: need at least email or body text',
    received: input
  }}];
}

return [{ json: {
  error: false,
  prospect_email: prospect_email.toLowerCase().trim(),
  prospect_name,
  subject,
  body,
  received_at,
  raw_input: input
}}];

// Signal Classifier: green / yellow / red
// Based on CMO Revenue Engine spec and Sales Handbook patterns

const { body, subject, prospect_email, prospect_name, received_at } = $json;

const text = (subject + ' ' + body).toLowerCase();

// === RED signals: not interested, unsubscribe, hostile ===
const RED_PATTERNS = [
  /\bunsubscribe\b/,
  /\bremove me\b/,
  /\bstop (emailing|contacting|messaging)\b/,
  /\bnot interested\b/,
  /\bno thanks\b/,
  /\bno thank you\b/,
  /\bplease (don'?t|do not) (contact|email|reach out)\b/,
  /\bwrong person\b/,
  /\bnot relevant\b/,
  /\bopt.?out\b/,
  /\bspam\b/,
  /\breport(ing|ed)? (as )?spam\b/,
  /\bstop\b.*\bplease\b/,
  /\bleave me alone\b/,
  /\bnot (the right|a good) fit\b/,
  /\bwe'?re (all )?set\b/,
  /\bwe (already )?have (a |everything )?(solution|tool|vendor)\b/
];

// === GREEN signals: interested, wants to talk ===
const GREEN_PATTERNS = [
  /\blet'?s (talk|chat|connect|discuss|set up|schedule|hop on)\b/,
  /\bi'?d (love|like) to (learn|hear|see|discuss|chat|talk|know)\b/,
  /\bsound(s)? (interesting|great|good|promising|compelling)\b/,
  /\btell me more\b/,
  /\bbook(ed)? (a )?(time|call|meeting|demo)\b/,
  /\bschedule (a )?(time|call|meeting|demo)\b/,
  /\bfree (this|next) week\b/,
  /\bopen (to|for) (a )?(call|chat|meeting|conversation|discussion)\b/,
  /\bsend (me |over )?(more )?(info|details|a demo|documentation|pricing)\b/,
  /\bwhat (does it|would it) (cost|look like)\b/,
  /\bhow (does|would) (it|this|guardspine) work\b/,
  /\bwe (are |'re )?(dealing|struggling|facing) (with )?\b/,
  /\bthis (is|hits|addresses) (exactly )?\b.*(pain|problem|challenge|issue)\b/,
  /\bintroduce (you|your team) to\b/,
  /\bloop(ing)? in\b.*(cto|ciso|vp|head|lead|director|manager)\b/,
  /\bcan (you|we) (do a |run a )?demo\b/,
  /\bcal\.com\b/,
  /\bcalendly\b/,
  /\bhere'?s my (calendar|availability)\b/,
  /\bpilot\b/,
  /\btrial\b/,
  /\bpoc\b/
];

// === YELLOW signals: needs more info, timing issue, polite deferral ===
const YELLOW_PATTERNS = [
  /\bnot (right )?now\b/,
  /\bmaybe (later|next|in a few)\b/,
  /\bcheck back (in|later|next)\b/,
  /\bbusy (right now|this|at the moment)\b/,
  /\binteresting but\b/,
  /\bneed(s)? (to )?(think|consider|evaluate|review|discuss internally)\b/,
  /\bwho (else |also )?(uses|is using) (this|guardspine|it)\b/,
  /\b(any|have) case stud(y|ies)\b/,
  /\bwhat('s| is) (the )?(pricing|cost)\b/,
  /\bforwarded? (this |it )?(to|along)\b/,
  /\bloop(ed|ing)? in\b/,
  /\bcc'?d\b/,
  /\btiming (is|isn'?t)\b/,
  /\bbudget (cycle|season|freeze)\b/,
  /\bq[1-4] (would be|might be|is) better\b/,
  /\bnext quarter\b/,
  /\bafter (the|our) \b/,
  /\bsend (me )?more (info|details|about)\b/,
  /\bwhat (sets you|makes you|differentiates)\b/
];

let signal = 'yellow'; // default to yellow if ambiguous
let confidence = 0.5;
let matched_patterns = [];

// Check RED first (highest priority)
let red_matches = 0;
for (const pattern of RED_PATTERNS) {
  if (pattern.test(text)) {
    red_matches++;
    matched_patterns.push({ type: 'red', pattern: pattern.source });
  }
}

// Check GREEN
let green_matches = 0;
for (const pattern of GREEN_PATTERNS) {
  if (pattern.test(text)) {
    green_matches++;
    matched_patterns.push({ type: 'green', pattern: pattern.source });
  }
}

// Check YELLOW
let yellow_matches = 0;
for (const pattern of YELLOW_PATTERNS) {
  if (pattern.test(text)) {
    yellow_matches++;
    matched_patterns.push({ type: 'yellow', pattern: pattern.source });
  }
}

// Decision logic
if (red_matches > 0 && green_matches === 0) {
  signal = 'red';
  confidence = Math.min(0.95, 0.6 + (red_matches * 0.1));
} else if (green_matches > 0 && red_matches === 0) {
  signal = 'green';
  confidence = Math.min(0.95, 0.6 + (green_matches * 0.1));
} else if (green_matches > red_matches) {
  // Mixed signals, green wins but lower confidence
  signal = 'green';
  confidence = 0.5;
} else if (red_matches > green_matches) {
  signal = 'red';
  confidence = 0.5;
} else if (yellow_matches > 0) {
  signal = 'yellow';
  confidence = Math.min(0.85, 0.5 + (yellow_matches * 0.1));
}

// Short body with no strong signals = yellow (needs human review)
if (body.length < 30 && matched_patterns.length === 0) {
  signal = 'yellow';
  confidence = 0.3;
  matched_patterns.push({ type: 'yellow', pattern: 'short_ambiguous_body' });
}

return [{ json: {
  signal,
  confidence,
  matched_patterns,
  match_counts: { green: green_matches, yellow: yellow_matches, red: red_matches },
  prospect_email,
  prospect_name,
  subject,
  body_preview: body.substring(0, 500),
  received_at,
  classified_at: new Date().toISOString()
}}];

// Prepare green signal DB update payload
const data = $json;
return [{ json: {
  prospect_email: data.prospect_email,
  signal_type: 'green',
  signal_notes: `Classified green (confidence: ${data.confidence}). Patterns: ${data.matched_patterns.map(p => p.pattern).join(', ')}`,
  funnel_stage: 'green_signal',
  last_response_at: data.received_at,
  response_snippet: data.body_preview.substring(0, 200),
  response_received: 1
}}];

// Prepare yellow signal DB update payload
const data = $json;
return [{ json: {
  prospect_email: data.prospect_email,
  signal_type: 'yellow',
  signal_notes: `Classified yellow (confidence: ${data.confidence}). Patterns: ${data.matched_patterns.map(p => p.pattern).join(', ')}`,
  funnel_stage: 'follow_up',
  last_response_at: data.received_at,
  response_snippet: data.body_preview.substring(0, 200),
  response_received: 1
}}];

// Prepare red signal DB update payload
const data = $json;
return [{ json: {
  prospect_email: data.prospect_email,
  signal_type: 'red',
  signal_notes: `Classified red (confidence: ${data.confidence}). Patterns: ${data.matched_patterns.map(p => p.pattern).join(', ')}`,
  funnel_stage: 'closed_lost',
  last_response_at: data.received_at,
  response_snippet: data.body_preview.substring(0, 200),
  response_received: 1
}}];

